import java.io.*;

public class Main {
    private static final BufferedReader reader = new BufferedReader(new InputStreamReader(System.in), 1024 * 10);
    private static final BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(System.out), 1024 * 10);

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        int k = nextInt();

        int nn = n;
        long ex = 1;
        while (n % 10 == 0) {
            n /= 10;
            k--;
        }
        while (k > 0) {
            if (n % 2 == 0) {
                ex *= 5;
                n /= 2;
                k--;
            } else if (n % 5 == 0) {
                ex *= 2;
                n /= 5;
                k--;
            } else {
                break;
            }
        }
        while (k > 0) {
            ex *= 10;
            k--;
        }

        writer.write(String.valueOf(ex * nn));
        writer.newLine();
        writer.flush();
    }

    private static int nextInt() throws IOException {
        int c;
        int res = 0;
        do {
            c = reader.read();
            if (c == -1)
                return res;
        } while (c < '0' || c > '9');
        res = c - '0';
        while (true) {
            c = reader.read();
            if (c < '0' || c > '9')
                return res;
            res *= 10;
            res += c - '0';
        }
    }
}

